-- 选修课官方目录：将 2026-2027-1 快照写入 elective_course_catalog。
-- 该迁移可重复执行；课程主数据与用户提交数据分表保存。

CREATE TABLE IF NOT EXISTS "elective_course_catalog" (
  "id" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "teacher" TEXT NOT NULL,
  "type" TEXT NOT NULL,
  "campus" TEXT NOT NULL,
  "category" TEXT,
  "course_code" TEXT,
  "credits" REAL,
  "department" TEXT,
  "source_term" TEXT NOT NULL,
  "source_label" TEXT NOT NULL,
  "source_url" TEXT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "idx_elective_catalog_identity"
  ON "elective_course_catalog" ("name", "teacher");

